// Some portions generated by Codex
package org.eclipse.rdf4j.benchmark.common;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.util.List;

import org.eclipse.rdf4j.benchmark.rio.util.ThemeDataSetGenerator;
import org.eclipse.rdf4j.benchmark.rio.util.ThemeDataSetGenerator.Theme;
import org.eclipse.rdf4j.model.IRI;
import org.eclipse.rdf4j.model.Literal;
import org.eclipse.rdf4j.model.Model;
import org.eclipse.rdf4j.model.util.Values;
import org.eclipse.rdf4j.model.vocabulary.RDF;
import org.eclipse.rdf4j.query.QueryLanguage;
import org.eclipse.rdf4j.query.parser.QueryParserUtil;
import org.junit.jupiter.api.Test;

class DataTransformationThemeTest {

	private static final String NAMESPACE = "http://example.com/theme/data-transformation/";

	@Test
	void dataTransformationThemeProvidesLiteralTransformationWorkload() {
		Theme theme = Theme.valueOf("DATA_TRANSFORMATION");
		Model model = ThemeDataSetGenerator.generate(theme);

		IRI recordType = Values.iri(NAMESPACE, "Record");
		IRI expectedGraph = Values.iri("http://example.com/theme/graph/data-transformation");
		IRI sourceText = Values.iri(NAMESPACE, "sourceText");
		IRI optionalText = Values.iri(NAMESPACE, "optionalText");
		long recordCount = model.filter(null, RDF.TYPE, recordType).size();
		long optionalCount = model.filter(null, optionalText, null).size();

		assertFalse(model.isEmpty());
		assertTrue(model.contexts().contains(expectedGraph));
		assertTrue(model.stream().allMatch(statement -> expectedGraph.equals(statement.getContext())));
		assertTrue(recordCount > 1_000, "The workload needs enough records for transformation queries");
		assertTrue(model.contains(null, sourceText, null));
		assertTrue(model.filter(null, sourceText, null).objects().stream().allMatch(Literal.class::isInstance));
		for (String part : List.of("partOne", "partTwo", "partThree", "partFour", "partFive")) {
			IRI predicate = Values.iri(NAMESPACE, part);
			assertTrue(model.contains(null, predicate, null), "Missing literal part " + part);
			assertTrue(model.filter(null, predicate, null).objects().stream().allMatch(Literal.class::isInstance));
		}
		assertEquals(0.39d, (recordCount - optionalCount) / (double) recordCount, 0.01d,
				"optionalText should be absent about 39% of the time");

		List<String> queries = ThemeQueryCatalog.queriesFor(theme);
		assertEquals(ThemeQueryCatalog.QUERY_COUNT, queries.size());
		for (String query : queries) {
			QueryParserUtil.parseQuery(QueryLanguage.SPARQL, query, null);
		}

		String allQueries = String.join("\n", queries);
		assertTrue(allQueries.contains("COUNT(DISTINCT"));
		assertTrue(allQueries.contains("LCASE"));
		assertTrue(allQueries.contains("UCASE"));
		assertTrue(allQueries.contains("STRLEN"));
		assertTrue(allQueries.contains("CONCAT"));
		assertTrue(allQueries.contains("IRI("));
		assertTrue(allQueries.contains("REGEX"));
		assertTrue(allQueries.contains("COALESCE"));
		assertTrue(allQueries.contains("OPTIONAL"));
	}

	@Test
	void optionalValueProbabilitySupportsConfiguredBounds() {
		ThemeDataSetGenerator.DataTransformationConfig config = ThemeDataSetGenerator.dataTransformationConfig()
				.withRecordCount(1_000)
				.withOptionalValueProbability(0.0d);
		Model noOptionalValues = ThemeDataSetGenerator.generateDataTransformation(config);
		assertEquals(0, noOptionalValues.filter(null, Values.iri(NAMESPACE, "optionalText"), null).size());

		config.withOptionalValueProbability(1.0d);
		Model allOptionalValues = ThemeDataSetGenerator.generateDataTransformation(config);
		assertEquals(1_000, allOptionalValues.filter(null, Values.iri(NAMESPACE, "optionalText"), null).size());
	}
}
